import xml.etree.ElementTree as ET

xml_path = os.path.join(work_dir, 'Contents', 'section0.xml')
tree = ET.parse(xml_path)
root = tree.getroot()

print("=== Checking linesegarray distribution ===")
ns_regex = re.compile(r'\{([^}]+)\}')

# Find the namespace URI
ns_uri = None
for elem in root.iter():
    tag = elem.tag
    if tag.startswith('{'):
        match = ns_regex.match(tag)
        if match:
            ns_uri = match.group(1)
            break

ns = {'ns0': ns_uri} if ns_uri else {}

for para in root.findall('.//ns0:p', ns):
    para_id = para.get('id', 'unknown')
    has_linesegarray = para.find('ns0:linesegarray', ns) is not None
    # Get text content
    texts = []
    for run in para.findall('.//ns0:run', ns):
        for t in run.findall('ns0:t', ns):
            if t.text:
                texts.append(t.text)
    text_content = ''.join(texts)
    print(f"  Para {para_id}: has_linesegarray={has_linesegarray}, text='{text_content[:40]}{'...' if len(text_content) > 40 else ''}'")
"}
